# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_mis_b import M
R=M+[['英语 mis- + represent','呈现得不准确、把事实讲歪'],['misrepresent','歪曲或不实地描述']]
I=M+[['英语 mis- + interpret','解释或领会得不对'],['misinterpret','曲解、误解']]
RD=M+[['古英语 misrǣdan → 中古英语 misreden','错误地劝告或读解'],['英语 misread','读错；看错局势或人的意思']]
SP=M+[['英语 mis- + spell','把字母拼错'],['misspell','拼写错误']]
WD=[
E('misrepresent','/ˌmɪsreprɪˈzent/','歪曲；不实地描述或呈现','把事实搬到别人面前时，搬出来的样子已经走了样。','mis- + represent；这里 represent 是呈现、描述，不只是“代表某个组织”。',R,'misrepresent someone’s views 是把某人的观点讲歪；misrepresent yourself 可能是把自己的身份或能力说得不实。它常带指责意味，但词本身没有保证每次失真都是故意的。','misrepresent the facts；misrepresent someone’s views；misrepresent something as something else。','misunderstand 是自己理解错了；misrepresent 是向别人呈现时说错或说歪了。理解对了也可能故意 misrepresent。',('The headline misrepresents what the researchers actually found.','标题歪曲了研究人员实际发现的内容。'),('Please don’t misrepresent my concern as opposition to the whole plan.','请不要把我的担忧说成是反对整个计划。'),sources=['https://en.wiktionary.org/wiki/misrepresent','https://www.etymonline.com/word/misrepresent']),
E('misrepresentation','/ˌmɪsreprɪzenˈteɪʃən/','歪曲；不实陈述；错误呈现','被讲歪的内容，或者把内容讲歪这件事。','可分析为 mis- + representation，也可联系 misrepresent + -ation；不必强行把名词当成一定晚于动词的产物。',M+[['英语 representation 加 mis-；与 misrepresent 同族','不准确的呈现或描述'],['misrepresentation','失真的陈述、呈现或相关行为']],'a misrepresentation of the facts 是对事实的歪曲。它既能表示一般意义上的失真，也能出现在商业或法律争议中，后者要依具体语境理解。不要把所有观点分歧都叫 misrepresentation。','a misrepresentation of the facts；a serious misrepresentation；correct a misrepresentation。','representation 是呈现；misrepresentation 是呈现有问题。disagreement 只表示不同意，并不证明对方歪曲了事实。',('The author called the review a misrepresentation of her argument.','作者认为那篇评论歪曲了她的论点。'),('The company corrected the misrepresentation in its brochure.','公司更正了宣传册中的不实描述。'),sources=['https://en.wiktionary.org/wiki/misrepresentation','https://www.etymonline.com/word/misrepresentation']),
E('miscommunication','/ˌmɪskəmjuːnɪˈkeɪʃən/','沟通失误；信息传达不畅','消息从一人到另一人的路上出了问题：没说清、没收到，或双方接上的意思不同。','mis- + communication；communication 是信息交流，加 mis- 表示交流出了偏差。',M+[['英语 communication 加 mis-','交流没有准确完成'],['miscommunication','沟通失误或交流中的误差']],'miscommunication 不一定有谁撒谎，也不一定是谁完全没能力理解。可能只是时间说得含糊、责任人没确认、邮件没送到。这个词强调沟通环节出了问题，通常比 blame“指责”更着眼过程。','a miscommunication between teams；due to miscommunication；avoid miscommunication。','misinformation 是错误信息本身；miscommunication 是交流过程出了问题。真实信息也可能在交流中被误解。',('A miscommunication between the two teams delayed the launch.','两个团队之间的沟通失误推迟了发布。'),('We confirmed the address in writing to avoid miscommunication.','我们用文字确认了地址，以免沟通出错。'),sources=['https://en.wiktionary.org/wiki/miscommunication','https://www.merriam-webster.com/dictionary/miscommunication']),
E('misinterpret','英 /ˌmɪsɪnˈtɜːprɪt/；美 /ˌmɪsɪnˈtɜːrprɪt/','误解；曲解；错误解读','同一段话、一个动作或一组数据，被你赋予了不对的意思。','mis- + interpret“解读、解释”。',I,'misinterpret silence as agreement 是把沉默误当同意。它常强调如何解释一个信号，所以不仅能说语言，也能说统计结果、表情和行为。并不是任何另一种解释都一定是误解，要看证据。','misinterpret a remark；misinterpret the data；misinterpret A as B。','mistranslate 特指翻译出错；misinterpret 范围更广，即使没有跨语言，也可能解读错。',('She misinterpreted my silence as a refusal.','她把我的沉默误解成了拒绝。'),('The report warns that the figures are easy to misinterpret.','报告提醒，这些数字很容易被误读。'),sources=['https://en.wiktionary.org/wiki/misinterpret','https://www.etymonline.com/word/misinterpret']),
E('misinterpretation','/ˌmɪsɪntɜːrprɪˈteɪʃən/','错误解读；曲解；误释','不对的解释已经形成了，可以把它指出、澄清或纠正。','mis- + interpretation；也可按 misinterpret + -ation 理解结构。',M+[['英语 interpretation 加 mis-，与 misinterpret 同族','解释、领会发生错误'],['misinterpretation','错误的解读或解释过程']],'a common misinterpretation 是经常出现的一种误读。例如相关关系被解读成因果关系，就可以说 a misinterpretation of the data。这个名词着重“解释成了什么”，而不只是看漏了一个字。','a misinterpretation of the results；a common misinterpretation；open to misinterpretation。','misreading 可以偏重读错或看错；misinterpretation 更突出意义解释。不过日常使用有很多重叠。',('The conclusion rests on a misinterpretation of the survey results.','这个结论建立在对调查结果的错误解读上。'),('The writer added a note to prevent misinterpretation.','作者加了一条说明，防止读者误解。'),sources=['https://en.wiktionary.org/wiki/misinterpretation','https://www.etymonline.com/word/misinterpretation']),
E('miscalculation','/ˌmɪskælkjəˈleɪʃən/','计算错误；估计失误；失策','账面数字算错，或者把现实中的代价、反应、难度估错了。','mis- + calculation；calculation 不只指算术，也可指盘算和估计。',M+[['英语 calculation 加 mis-','计算或判断中出现偏差'],['miscalculation','算错；计划依据中的估计错误']],'miscalculation 能说预算加错，也能说低估对手的反应。a strategic miscalculation 往往没有一张真的算术草稿，意思是计划时算错了形势。','a costly miscalculation；a strategic miscalculation；a miscalculation of the cost。','miscalculation 强调估计过程出错；misfortune 是遭遇不幸，并不一定是判断造成的。',('A small miscalculation left us short of materials.','一个小小的计算错误导致我们的材料不够。'),('Ignoring customer complaints proved to be a costly miscalculation.','忽视客户投诉最终证明是代价高昂的判断失误。'),sources=['https://en.wiktionary.org/wiki/miscalculation','https://www.merriam-webster.com/dictionary/miscalculation']),
E('misread','现在时 /ˌmɪsˈriːd/；过去式、过去分词 /ˌmɪsˈred/','读错；误判；误解','可以是把字看错，也可以是把一个人的态度或整个形势看错。','mis- + read；历史有古英语 misrǣdan。现在与过去拼写相同，读音不同。',RD,'misread the date 是日期看错；misread the room 是没有看准现场人的情绪或反应。read 本来就能指理解一个情境，misread 随着它一起从读文字扩展到看人、看局势。','misread a label；misread the situation；misread someone’s intentions。','I often misread 读 /riːd/；I misread it yesterday 读 /red/。不要因为前面加了 mis- 就忘记 read 的不规则读音。',('I misread the timetable and arrived an hour early.','我看错了时刻表，早到了一个小时。'),('He misread her nervousness as a lack of interest.','他把她的紧张误解成了不感兴趣。'),sources=['https://en.wiktionary.org/wiki/misread','https://www.etymonline.com/word/misread']),
E('misspell','/ˌmɪsˈspel/','拼错；把字拼写错','想写的是这个词，排出来的字母却不对。','mis- + spell；第一个 s 属于 mis-，第二个 s 属于 spell，所以保留双 s。',SP,'misspell a name 是把名字拼错。过去式和过去分词常用 misspelled，英式还常见 misspelt。这个词关注字母拼写，不是说把意思翻译错，也不是说发音不标准。','misspell a word；misspell someone’s name；a frequently misspelled word。','mispronounce 是读音说错，misspell 是字母拼错。说得对也可能写错，反过来也一样。',('I always misspell this street name.','我总是把这条街的名字拼错。'),('Her surname was misspelled on the certificate.','证书把她的姓拼错了。'),sources=['https://en.wiktionary.org/wiki/misspell','https://www.etymonline.com/word/misspell']),
E('misspelling','/ˌmɪsˈspelɪŋ/','拼写错误；错误拼法','把拼错的结果单独拿出来数：这里一处，那里又一处。','mis- + spelling；也可联系 misspell + -ing。双 s 仍是两个成分相接。',SP+[['spelling 加 mis-；或 misspell 的 -ing 名词形式','错误拼写或某个具体错误拼法']],'a misspelling 可以是一处拼写错误，也可以指某个词常见的错误拼法。check for misspellings 是检查有没有拼写错误。语法、标点或用词不当不一定属于 misspelling。','a common misspelling；correct a misspelling；check for misspellings。','typo 是打字或排印失误；misspelling 是拼写不正确。有人因为不认识正确拼法写错，也属于 misspelling，却未必是手误。',('The editor corrected several misspellings in the draft.','编辑改正了草稿中的几处拼写错误。'),('That version of the name is a common misspelling.','那个版本的名字是一种常见误拼。'),sources=['https://en.wiktionary.org/wiki/misspelling','https://www.merriam-webster.com/dictionary/misspelling']),
E('misjudge','/ˌmɪsˈdʒʌdʒ/','判断错；估错；误判某人','心里对大小、距离、能力或人品作了判断，但判断不准。','mis- + judge“判断”；judge 在这里不一定指法官裁决。',M+[['英语 mis- + judge','作出错误判断'],['misjudge','误估情况；误判一个人']],'misjudge the distance 是距离估错；misjudge someone 是对某人看错了，可以是看得太好，也可以是看得太坏。这个词本身没有规定错误方向，后面的情境才告诉你。','misjudge the distance；misjudge someone’s ability；badly misjudge a situation。','underestimate 一定偏低，overestimate 一定偏高；misjudge 只说错了，不限定高低。',('I misjudged the distance and stopped too late.','我估错了距离，刹停得太晚。'),('I misjudged her at first; she turned out to be very generous.','起初我看错了她，后来发现她很慷慨。'),sources=['https://en.wiktionary.org/wiki/misjudge','https://www.etymonline.com/word/misjudge']),
]
